-- Vanguard: restore the patrol of the Tanaris Dune Smasher spawn (guid 23119).
-- Updates/4827 gives 23119 MovementType 2 and this 31-point path; the old
-- db-fix (startup_log_fixes.sql, 2026-08-30) deleted it on the mistaken
-- assumption that creature.id = 0 meant an orphaned spawn (the entry comes
-- from spawn_group_entry). Without it mangosd logs "doesn't have waypoint path 0".
-- Rows copied verbatim from Updates/4827. Safe to re-run.

SET @CGUID := 23119;
DELETE FROM `creature_movement` WHERE `Id` = @CGUID;
